import SoundGenerator, { SoundGeneratorOptions } from './SoundGenerator.js';
type SelfOptions = {
    crossFadeProperty?: NumberProperty | null;
    initialCrossFadeValue?: number;
};
type CrossFadeSoundClipOptions = SoundGeneratorOptions & SelfOptions;
declare class CrossFadeSoundClip extends SoundGenerator implements TSoundPlayer {
    readonly crossFadeProperty: NumberProperty;
    private readonly soundClipA;
    private readonly soundClipB;
    /**
     * @param audioBufferA - audio buffer for sound A
     * @param audioBufferB - audio buffer for sound B
     * @param [providedOptions]
     */
    constructor(audioBufferA: WrappedAudioBuffer, audioBufferB: WrappedAudioBuffer, providedOptions?: CrossFadeSoundClipOptions);
    play(): void;
    stop(): void;
    setPlaybackRate(playbackRate: number): void;
}
export default CrossFadeSoundClip;
